import asyncio
import websockets
import json
import threading
import queue

class StreamingSpeechToText:
    def __init__(self, api_key):
        self.api_key = api_key
        self.audio_queue = queue.Queue()
        self.result_queue = queue.Queue()
        self.recognition_thread = None
        self.running = False
        self.websocket = None

    def start_streaming(self, sample_rate=16000, language_code='en-US'):
        self.running = True
        self.recognition_thread = threading.Thread(
            target=self._recognition_loop,
            args=(sample_rate, language_code),
            daemon=True
        )
        self.recognition_thread.start()

    def _recognition_loop(self, sample_rate, language_code):
        asyncio.run(self._async_recognition_loop(sample_rate, language_code))

    async def _async_recognition_loop(self, sample_rate, language_code):
        uri = "wss://api.assemblyai.com/v2/realtime/ws?sample_rate=" + str(sample_rate)
        try:
            async with websockets.connect(
                uri,
                extra_headers={"Authorization": self.api_key}
            ) as websocket:
                self.websocket = websocket
                await websocket.send(json.dumps({
                    "language_code": language_code
                }))
                await self._handle_messages(websocket)
        except Exception as e:
            self.result_queue.put(("error", str(e)))
        finally:
            self.running = False

    async def _handle_messages(self, websocket):
        while self.running:
            try:
                message = await asyncio.wait_for(websocket.recv(), timeout=0.1)
                data = json.loads(message)
                message_type = data.get("message_type")

                if message_type == "PartialTranscript":
                    transcript = data.get("text", "")
                    confidence = data.get("confidence", 0.0)
                    self.result_queue.put(("partial", {
                        "transcript": transcript,
                        "confidence": confidence,
                        "words": data.get("words", [])
                    }))
                elif message_type == "FinalTranscript":
                    transcript = data.get("text", "")
                    confidence = data.get("confidence", 0.0)
                    self.result_queue.put(("final", {
                        "transcript": transcript,
                        "confidence": confidence,
                        "words": data.get("words", []),
                        "audio_start": data.get("audio_start"),
                        "audio_end": data.get("audio_end")
                    }))
                elif message_type == "SessionBegins":
                    self.result_queue.put(("session_start", data.get("session_id")))
                elif message_type == "SessionTerminated":
                    self.result_queue.put(("session_end", None))
                    break
            except asyncio.TimeoutError:
                continue
            except Exception as e:
                self.result_queue.put(("error", str(e)))
                break

    def send_audio(self, audio_chunk):
        if self.running and self.websocket:
            asyncio.run_coroutine_threadsafe(
                self._send_audio_chunk(audio_chunk),
                asyncio.get_event_loop()
            )

    async def _send_audio_chunk(self, audio_chunk):
        try:
            await self.websocket.send(json.dumps({"audio_data": audio_chunk.hex()}))
        except Exception as e:
            self.result_queue.put(("error", f"Send error: {str(e)}"))

    def get_results(self):
        results = []
        while not self.result_queue.empty():
            results.append(self.result_queue.get())
        return results

    def stop_streaming(self):
        self.running = False
        if self.recognition_thread:
            self.recognition_thread.join(timeout=2)
